<?php
$pdo = db();
$canManageProgression = in_array($user['role'], ['Administrator','Head'], true);
if (isset($_GET['progression'])) {
    if (!$canManageProgression) { http_response_code(403); echo '<div class="alert alert-error">Only school administrators and heads can manage learner progression.</div>'; return; }
    require __DIR__ . '/progression.php';
    return;
}
$canEditStudents = in_array($user['role'], ['Administrator','Head','Clerk'], true);
$canViewPrivateStudentData = in_array($user['role'], ['Administrator','Head','Clerk'], true);
$unlinkedCurrentEnrollments=0;
if($canManageProgression){$currentYears=$pdo->query('SELECT academic_year FROM school_terms WHERE is_current=1')->fetchAll(PDO::FETCH_COLUMN);if(count($currentYears)===1){$check=$pdo->prepare("SELECT COUNT(*) FROM student_enrolments e JOIN students s ON s.id=e.student_id WHERE e.academic_year=:year AND e.end_date IS NULL AND s.status='Active' AND (s.form_level<>e.form_level OR COALESCE(s.stream,'')<>COALESCE(e.stream,'') OR NOT EXISTS(SELECT 1 FROM class_groups c WHERE c.academic_year=e.academic_year AND c.form_level=e.form_level AND c.stream=COALESCE(e.stream,'')))");$check->execute(['year'=>$currentYears[0]]);$unlinkedCurrentEnrollments=(int)$check->fetchColumn();}}
$where = [];
$params = [];
if ($user['role'] === 'Teacher') {
    $where[] = "EXISTS (SELECT 1 FROM class_groups cg LEFT JOIN class_subjects cs ON cs.class_id=cg.id WHERE cg.form_level=s.form_level AND COALESCE(cg.stream,'')=COALESCE(s.stream,'') AND cg.academic_year=YEAR(CURDATE()) AND (cg.class_teacher_id=:teacher_class OR cs.teacher_id=:teacher_subject))";
    $params['teacher_class'] = (int)$user['id'];
    $params['teacher_subject'] = (int)$user['id'];
}
$scopeSql = $where ? ' AND '.implode(' AND ', $where) : '';
$id = filter_var($_GET['id'] ?? null, FILTER_VALIDATE_INT);
$editId = filter_var($_GET['edit'] ?? null, FILTER_VALIDATE_INT);
$profile = null;
$guardian = null;
$enrolmentHistory = [];
if ($id) {
    $stmt = $pdo->prepare("SELECT s.* FROM students s WHERE s.id=:id $scopeSql LIMIT 1");
    $stmt->execute(['id'=>$id] + $params);
    $profile = $stmt->fetch();
    if (!$profile) { http_response_code(404); echo '<div class="alert alert-warn">Learner record not found.</div>'; return; }
    $stmt = $pdo->prepare('SELECT * FROM student_guardians WHERE student_id=:id ORDER BY is_primary DESC, id');
    $stmt->execute(['id'=>$id]);
    $guardian = $stmt->fetch() ?: null;
    $stmt = $pdo->prepare('SELECT academic_year,term_number,form_level,stream,start_date,end_date,status,change_reason FROM student_enrolments WHERE student_id=:id ORDER BY start_date DESC,id DESC');
    $stmt->execute(['id'=>$id]);
    $enrolmentHistory = $stmt->fetchAll();
}
$editStudent = null;
$editGuardian = null;
if ($editId && $canEditStudents) {
    $stmt = $pdo->prepare('SELECT * FROM students WHERE id=:id LIMIT 1');
    $stmt->execute(['id'=>$editId]);
    $editStudent = $stmt->fetch() ?: null;
    if ($editStudent) {
        $stmt = $pdo->prepare('SELECT * FROM student_guardians WHERE student_id=:id AND is_primary=1 ORDER BY id LIMIT 1');
        $stmt->execute(['id'=>$editId]);
        $editGuardian = $stmt->fetch() ?: null;
    }
}
$query = trim((string)($_GET['q'] ?? ''));
$formFilter = filter_var($_GET['form'] ?? null, FILTER_VALIDATE_INT);
$statusFilter = (string)($_GET['status'] ?? 'Active');
$sexFilter = (string)($_GET['sex'] ?? '');
$listWhere = $where;
$listParams = $params;
if (!$id) {
    if ($query !== '') {
        $listWhere[] = '(s.first_name LIKE :q1 OR s.last_name LIKE :q2 OR s.admission_no LIKE :q3)';
        $listParams += ['q1'=>'%'.$query.'%','q2'=>'%'.$query.'%','q3'=>'%'.$query.'%'];
    }
    if ($formFilter !== false && $formFilter >= 1 && $formFilter <= 6) { $listWhere[]='s.form_level=:form_level'; $listParams['form_level']=$formFilter; }
    if (in_array($statusFilter,['Active','Transferred','Withdrawn','Graduated','All'],true) && $statusFilter !== 'All') { $listWhere[]='s.status=:status'; $listParams['status']=$statusFilter; }
    if (in_array($sexFilter,['F','M'],true)) { $listWhere[]='s.sex=:sex'; $listParams['sex']=$sexFilter; }
}
$listSqlWhere = $listWhere ? ' WHERE '.implode(' AND ', $listWhere) : '';
$statsStmt = $pdo->prepare("SELECT COUNT(*) AS total, SUM(s.form_level<=4) AS olevel, SUM(s.form_level>=5) AS alevel FROM students s WHERE s.status='Active'".($where ? ' AND '.implode(' AND ', $where) : ''));
$statsStmt->execute($params);
$stats = $statsStmt->fetch() ?: ['total'=>0,'olevel'=>0,'alevel'=>0];
$pageNo = max(1, (int)($_GET['p'] ?? 1));
$pageSize = 20;
$countStmt = $pdo->prepare("SELECT COUNT(*) FROM students s $listSqlWhere");
$countStmt->execute($listParams);
$rowCount = (int)$countStmt->fetchColumn();
$pageCount = max(1, (int)ceil($rowCount/$pageSize));
$pageNo = min($pageNo,$pageCount);
$offset = ($pageNo-1)*$pageSize;
$listStmt = $pdo->prepare("SELECT s.id,s.admission_no,s.first_name,s.last_name,s.sex,s.date_of_birth,s.form_level,s.stream,s.status,
    COALESCE(g.guardian_count,0) AS guardian_count,COALESCE(g.has_consent,0) AS has_consent
    FROM students s LEFT JOIN (SELECT student_id,COUNT(*) guardian_count,MAX(consent_status='Granted') has_consent FROM student_guardians GROUP BY student_id) g ON g.student_id=s.id
    $listSqlWhere ORDER BY s.last_name,s.first_name LIMIT $pageSize OFFSET $offset");
$listStmt->execute($listParams);
$studentRows = $listStmt->fetchAll();
$filterQuery = $_GET;
unset($filterQuery['p'],$filterQuery['id'],$filterQuery['edit'],$filterQuery['add']);
$queryString = http_build_query($filterQuery);
?>
<?php if ($profile): ?>
  <div class="page-heading"><div><div class="eyebrow">LEARNER RECORD</div><h1><?= h($profile['first_name'].' '.$profile['last_name']) ?></h1><p class="subheading"><?= h($profile['admission_no']) ?> · Form <?= (int)$profile['form_level'] ?><?= $profile['stream'] ? ' · '.h($profile['stream']) : '' ?></p></div><div class="page-actions"><a class="outline-button" href="?page=students">← All learners</a><?php if ($canEditStudents): ?><a class="primary-button" href="?page=students&edit=<?= (int)$profile['id'] ?>">Edit learner</a><?php endif; ?></div></div>
  <div class="student-profile-grid"><section class="panel profile-panel"><div class="profile-section-head"><h2>Personal details</h2><span class="status-pill"><?= h($profile['status']) ?></span></div><dl class="detail-grid"><div><dt>Sex</dt><dd><?= $profile['sex']==='F'?'Female':'Male' ?></dd></div><div><dt>Date of birth</dt><dd><?= $profile['date_of_birth'] ? h(date('d M Y',strtotime($profile['date_of_birth']))) : 'Not recorded' ?></dd></div><div><dt>Current form</dt><dd>Form <?= (int)$profile['form_level'] ?><?= $profile['stream'] ? ' · '.h($profile['stream']) : '' ?></dd></div><div><dt>Admission date</dt><dd><?= h(date('d M Y',strtotime($profile['created_at']))) ?></dd></div><?php if ($canViewPrivateStudentData): ?><div><dt>National ID</dt><dd><?= $profile['national_id'] ? h($profile['national_id']) : 'Not recorded' ?></dd></div><div><dt>Home address</dt><dd><?= $profile['address'] ? nl2br(h($profile['address'])) : 'Not recorded' ?></dd></div><?php endif; ?></dl></section>
  <?php if ($canViewPrivateStudentData): ?><section class="panel profile-panel"><div class="profile-section-head"><h2>Parent / legal guardian</h2><?php if ($guardian): ?><span class="consent-pill <?= strtolower($guardian['consent_status']) ?>"><?= h($guardian['consent_status']) ?> consent</span><?php endif; ?></div><?php if ($guardian): ?><dl class="detail-grid"><div><dt>Name</dt><dd><?= h($guardian['full_name']) ?></dd></div><div><dt>Relationship</dt><dd><?= h($guardian['relationship']) ?></dd></div><div><dt>Phone</dt><dd><?= h($guardian['phone']) ?></dd></div><div><dt>Email</dt><dd><?= $guardian['email'] ? h($guardian['email']) : 'Not recorded' ?></dd></div><div><dt>Consent method</dt><dd><?= $guardian['consent_method'] ? h($guardian['consent_method']) : 'Not recorded' ?></dd></div><div><dt>Consent recorded</dt><dd><?= $guardian['consent_recorded_at'] ? h(date('d M Y',strtotime($guardian['consent_recorded_at']))) : 'Not recorded' ?></dd></div></dl><?php else: ?><p class="subheading">No guardian contact has been recorded.</p><?php endif; ?><p class="privacy-note">Guardian contact details are restricted to authorised school staff. Record consent using the school’s approved privacy notice and process.</p></section><?php endif; ?></div>
  <section class="panel learners-panel history-panel"><div class="panel-heading"><div><h2>Enrolment history</h2><p>Class placement changes and school-year records</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Academic year</th><th>Term</th><th>Form / stream</th><th>From</th><th>To</th><th>Record status</th></tr></thead><tbody><?php if (!$enrolmentHistory): ?><tr><td colspan="6" class="empty-cell">No enrolment history recorded.</td></tr><?php endif; ?><?php foreach ($enrolmentHistory as $enrol): ?><tr><td><?= (int)$enrol['academic_year'] ?></td><td>Term <?= (int)$enrol['term_number'] ?></td><td>Form <?= (int)$enrol['form_level'] ?><?= $enrol['stream'] ? ' · '.h($enrol['stream']) : '' ?></td><td><?= h(date('d M Y',strtotime($enrol['start_date']))) ?></td><td><?= $enrol['end_date'] ? h(date('d M Y',strtotime($enrol['end_date']))) : '—' ?></td><td><?= h($enrol['status']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php else: ?>
  <div class="page-heading"><div><div class="eyebrow">SCHOOL DIRECTORY</div><h1>Learners</h1><p class="subheading">Enrolment records, forms, guardian contacts and class history.</p></div><div class="page-actions"><?php if ($canManageProgression): ?><a class="outline-button" href="?page=students&progression=1">Class progression</a><?php endif; ?><?php if ($canEditStudents): ?><a class="primary-button" href="?page=students&add=1"><span>＋</span> Add a learner</a><?php endif; ?></div></div>
  <?php if($canManageProgression&&$unlinkedCurrentEnrollments): ?><div class="alert alert-warn"><?= number_format($unlinkedCurrentEnrollments) ?> active learner enrollment(s) for the current year do not match their learner class or a configured class group. These records will not appear in class registers and reports until Academics → Classes is configured to match their enrollment.</div><?php endif; ?>
  <section class="stat-strip"><div><span>Active learners</span><b><?= number_format((int)$stats['total']) ?></b></div><div><span>O-Level · Forms 1–4</span><b><?= number_format((int)$stats['olevel']) ?></b></div><div><span>A-Level · Forms 5–6</span><b><?= number_format((int)$stats['alevel']) ?></b></div><div><span>Records shown</span><b><?= number_format($rowCount) ?></b></div></section>
  <?php if($canEditStudents): $csvPreview=$_SESSION['student_import_preview']??null; ?><section class="panel settings-panel"><div class="panel-heading"><div><h2>Import learners from CSV</h2><p>Preview and validate up to 2,000 learners before importing them as one transaction.</p></div><a class="outline-button" href="actions/student_import_template.php">⇩ Download template</a></div><?php if(is_array($csvPreview)): $previewFresh=(int)($csvPreview['created_at']??0)>=time()-1200;$previewRows=is_array($csvPreview['rows']??null)?$csvPreview['rows']:[];$previewErrors=is_array($csvPreview['errors']??null)?$csvPreview['errors']:[]; ?><div class="alert <?= $previewFresh&&!$previewErrors?'alert-success':'alert-warn' ?>">File: <?= h($csvPreview['file_name']??'CSV') ?> · <?= count($previewRows) ?> valid learner row(s) · <?= count($previewErrors) ?> issue(s)<?php if(!$previewFresh): ?> · Preview expired; upload the file again.<?php elseif(!$previewErrors): ?> · No issues found. Review the sample rows and confirm to import.<?php endif; ?></div><?php if($previewErrors): ?><div class="table-scroll"><table class="data-table"><thead><tr><th>CSV row</th><th>Issue</th></tr></thead><tbody><?php foreach(array_slice($previewErrors,0,30) as $issue): ?><tr><td><?= (int)$issue['row']?:'Header' ?></td><td><?= h($issue['message']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(count($previewErrors)>30): ?><p class="muted-cell">First 30 issues shown of <?= count($previewErrors) ?>.</p><?php endif; ?><?php endif; ?><?php if($previewRows): ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Admission no.</th><th>Learner</th><th>Form / stream</th><th>Sex</th><th>Guardian consent</th></tr></thead><tbody><?php foreach(array_slice($previewRows,0,20) as $row): ?><tr><td><?= h($row['admission_no']) ?></td><td><?= h($row['first_name'].' '.$row['last_name']) ?></td><td>Form <?= (int)$row['form_level'] ?><?= $row['stream']?' · '.h($row['stream']):'' ?></td><td><?= $row['sex']==='F'?'Female':'Male' ?></td><td><?= $row['guardian_name']?'Pending':'No contact' ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(count($previewRows)>20): ?><p class="muted-cell">First 20 of <?= count($previewRows) ?> valid learner rows shown.</p><?php endif; ?><?php endif; ?><p class="privacy-note">Guardian consent is always imported as Pending. Review contacts and obtain consent through the school’s approved process before creating guardian portal accounts.</p><div class="form-actions"><?php if($previewFresh&&$previewRows&&!$previewErrors): ?><form method="post" action="actions/student_import_confirm.php" onsubmit="return confirm('Import <?= count($previewRows) ?> learner records? This creates learner records and enrolment history.')"><?= csrf_field() ?><input type="hidden" name="preview_token" value="<?= h($csvPreview['token']??'') ?>"><button class="primary-button">Confirm import of <?= count($previewRows) ?> learner(s)</button></form><?php endif; ?><form method="post" action="actions/student_import_cancel.php"><?= csrf_field() ?><button class="outline-button">Discard preview</button></form></div><?php else: ?><form method="post" action="actions/student_import_preview.php" enctype="multipart/form-data" class="compact-form"><?= csrf_field() ?><label>CSV file<input type="file" name="learner_csv" accept=".csv,text/csv" required></label><button class="primary-button">Upload and preview</button></form><p class="privacy-note">CSV columns: admission_no, first_name, last_name, sex (F/M), form_level (1–6), stream, date_of_birth (YYYY-MM-DD), national_id, guardian_name, guardian_relationship, guardian_phone, guardian_email, address. Only the first five columns are required. Files are limited to 2 MB.</p><?php endif; ?></section><?php endif; ?>
  <section class="panel learners-panel"><form class="list-toolbar" method="get" action="/"><input type="hidden" name="page" value="students"><div class="search-box"><span>⌕</span><input id="learnerSearch" name="q" value="<?= h($query) ?>" placeholder="Search name or admission number" aria-label="Search learners"></div><div class="toolbar-right"><select class="select-control" name="form"><option value="">All forms</option><?php for($i=1;$i<=6;$i++): ?><option value="<?= $i ?>" <?= $formFilter===$i?'selected':'' ?>>Form <?= $i ?></option><?php endfor; ?></select><select class="select-control" name="status"><option value="Active" <?= $statusFilter==='Active'?'selected':'' ?>>Active</option><option value="Transferred" <?= $statusFilter==='Transferred'?'selected':'' ?>>Transferred</option><option value="Withdrawn" <?= $statusFilter==='Withdrawn'?'selected':'' ?>>Withdrawn</option><option value="Graduated" <?= $statusFilter==='Graduated'?'selected':'' ?>>Graduated</option><option value="All" <?= $statusFilter==='All'?'selected':'' ?>>All statuses</option></select><select class="select-control" name="sex"><option value="">All sexes</option><option value="F" <?= $sexFilter==='F'?'selected':'' ?>>Female</option><option value="M" <?= $sexFilter==='M'?'selected':'' ?>>Male</option></select><button class="outline-button" type="submit">Filter</button><?php if ($canViewPrivateStudentData): ?><a class="outline-button" href="actions/student_export.php<?= $queryString ? '?'.h($queryString) : '' ?>">⇩ Export</a><?php endif; ?></div></form>
  <div class="table-scroll"><table class="data-table"><thead><tr><th>Learner</th><th>Admission no.</th><th>Form / stream</th><th>Sex</th><th>Status</th><?php if ($canViewPrivateStudentData): ?><th>Guardian consent</th><?php endif; ?><th></th></tr></thead><tbody><?php if (!$studentRows): ?><tr><td colspan="<?= $canViewPrivateStudentData?7:6 ?>" class="empty-cell">No learners match these filters.</td></tr><?php endif; ?><?php foreach ($studentRows as $s): $fullName=$s['first_name'].' '.$s['last_name']; $initial=strtoupper(substr($s['first_name'],0,1).substr($s['last_name'],0,1)); ?><tr><td><a class="learner-cell" href="?page=students&id=<?= (int)$s['id'] ?>"><span class="learner-avatar"><?= h($initial) ?></span><b><?= h($fullName) ?></b></a></td><td class="muted-cell"><?= h($s['admission_no']) ?></td><td>Form <?= (int)$s['form_level'] ?><?= $s['stream'] ? ' · '.h($s['stream']) : '' ?></td><td><?= $s['sex']==='F'?'Female':'Male' ?></td><td><span class="status-pill"><?= h($s['status']) ?></span></td><?php if ($canViewPrivateStudentData): ?><td><?php if (!(int)$s['guardian_count']): ?><span class="consent-pill pending">No guardian</span><?php else: ?><span class="consent-pill <?= (int)$s['has_consent']?'granted':'pending' ?>"><?= (int)$s['has_consent']?'Recorded':'Pending' ?></span><?php endif; ?></td><?php endif; ?><td class="row-actions"><?php if ($canEditStudents): ?><a class="outline-button compact-button" href="?page=students&edit=<?= (int)$s['id'] ?>">Edit</a><?php else: ?><a class="text-button" href="?page=students&id=<?= (int)$s['id'] ?>">View →</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
  <div class="pagination"><span>Showing <?= $rowCount ? $offset+1 : 0 ?>–<?= min($offset+$pageSize,$rowCount) ?> of <?= number_format($rowCount) ?></span><div><?php if ($pageNo>1): ?><a class="outline-button compact-button" href="?page=students&<?= h($queryString) ?>&p=<?= $pageNo-1 ?>">← Previous</a><?php endif; ?><?php if ($pageNo<$pageCount): ?><a class="outline-button compact-button" href="?page=students&<?= h($queryString) ?>&p=<?= $pageNo+1 ?>">Next →</a><?php endif; ?></div></div></section>
