      <div class="form-section-title guardian-title">Parent / legal guardian</div><div class="form-grid"><label>Guardian name<input name="guardian_name" value="<?= h($editGuardian['full_name'] ?? $editStudent['guardian_name'] ?? '') ?>" maxlength="160"></label><label>Relationship<select name="guardian_relationship"><option value="">Select</option><?php foreach(['Parent','Legal guardian','Grandparent','Other relative','Other'] as $relationship): ?><option <?= ($editGuardian['relationship'] ?? '')===$relationship?'selected':'' ?>><?= h($relationship) ?></option><?php endforeach; ?></select></label><label>Phone<input name="guardian_phone" value="<?= h($editGuardian['phone'] ?? $editStudent['guardian_phone'] ?? '') ?>" maxlength="30" placeholder="+263 7X XXX XXXX"></label><label>Email<input type="email" name="guardian_email" value="<?= h($editGuardian['email'] ?? $editStudent['guardian_email'] ?? '') ?>" maxlength="160"></label><label>Consent status<select name="guardian_consent_status"><?php foreach(['Pending','Granted','Revoked'] as $consentStatus): ?><option value="<?= h($consentStatus) ?>" <?= ($editGuardian['consent_status'] ?? 'Pending')===$consentStatus?'selected':'' ?>><?= h($consentStatus) ?></option><?php endforeach; ?></select></label><label>Consent method<select name="consent_method"><option value="">Not recorded</option><?php foreach(['Written','Electronic','In person'] as $method): ?><option <?= ($editGuardian['consent_method'] ?? '')===$method?'selected':'' ?>><?= h($method) ?></option><?php endforeach; ?></select></label><label>Consent reference <span class="optional">Optional, no document upload</span><input name="consent_reference" value="<?= h($editGuardian['consent_reference'] ?? '') ?>" maxlength="180" placeholder="Register or form reference"></label></div><p class="privacy-note">Changing or clearing a linked guardian’s identity or contact, or changing consent away from Granted, removes the old portal link. Verify consent and create/link an account again before restoring access. Record consent according to the school’s approved privacy process.</p>
      <div class="form-actions"><a class="outline-button" href="?page=students">Cancel</a><button class="primary-button"><?= $editing?'Save changes':'Create learner record' ?></button></div>
    </form></div></div>
  <?php endif; ?>
